'use strict';

var index = require('./index-KWxdc1K1.cjs');
require('quansync');

function getToJsonSchemaFn() {
  return (schema, options) => (
    // `arktype` can't describe what a morph outputs, so a schema with one is
    // written as the input it accepts unless the output is asked for, which
    // then allows any value where the morph is.
    schema[index.ioOf(options) === "output" ? "out" : "in"].toJsonSchema(
      options
    )
  );
}

exports.default = getToJsonSchemaFn;
